mapper.select:
select br.*
from batch_rabbits br
inner join batches b on b.id = br.batch_id
where br.batch_id = #{batchId}
  and br.is_active = true
  and b.house_id = #{houseId}
  and br.rabbit_id in

      #{rabbitId}

order by br.rabbit_id, br.id
for update

mapper.update:
update batch_rabbits br
inner join rabbits r on r.id = br.rabbit_id
inner join (
    select selected_ids.id
    from (
        select scoped_br.id
        from batch_rabbits scoped_br
        inner join batches scoped_b on scoped_b.id = scoped_br.batch_id
        where scoped_b.house_id = #{houseId}
          and scoped_br.batch_id = #{batchId}
          and scoped_br.is_active = true
        order by scoped_br.id
        limit #{limit}
    ) selected_ids
) selected on selected.id = br.id
set br.is_active = false,
    br.exit_date = #{exitDate},
    br.remark = #{remark},
    br.update_by = #{updateBy},
    br.update_time = now(),
    r.state_version = r.state_version + 1,
    r.update_by = #{updateBy},
    r.update_time = now()
where r.house_id = #{houseId}
  and br.batch_id = #{batchId}
  and br.is_active = true

update batch_rabbits
set is_event_notified = true,
    event_notify_date = now(),
    update_by = #{updateBy},
    update_time = now()
where id in (
    select id
    from (
        select br.id
        from batch_rabbits br
        inner join batches b on b.id = br.batch_id
        where b.house_id = #{houseId}
          and br.is_active = true
          and br.next_event_date is not null
          and br.next_event_date <= #{today}
          and br.is_event_notified = false

        order by br.id
        limit #{limit}
    ) due_batch_events
)

mapper.select:
with pending_by_cycle as ( select wt.cycle_id, min(wt.due_time) as next_due_at from work_tasks wt where wt.batch_id = #{batchId} and wt.status = 'PENDING' and wt.cycle_id is not null group by wt.cycle_id ), ranked_open_cycles as ( select c.id, c.batch_id, c.mother_rabbit_id, c.male_rabbit_id, c.stage, p.next_due_at, row_number() over ( partition by c.batch_id, c.mother_rabbit_id order by case when p.next_due_at is null then 1 else 0 end, p.next_due_at, case when c.stage = 'AWAIT_WEANING' then 1 else 0 end, c.cycle_no desc, c.id desc ) as row_no from breeding_cycles c left join pending_by_cycle p on p.cycle_id = c.id where c.batch_id = #{batchId} and c.lifecycle = 'OPEN' ), current_cycles as ( select * from ranked_open_cycles where row_no = 1 ), cycle_stats as ( select c.batch_id, c.mother_rabbit_id, count(*) as cycle_count, max(c.id) as latest_cycle_id from breeding_cycles c where c.batch_id = #{batchId} group by c.batch_id, c.mother_rabbit_id ), event_stats as ( select e.batch_id, e.mother_rabbit_id, count(*) as operation_count, max(e.occurred_at) as last_operation_at from repro_events e where e.batch_id = #{batchId} group by e.batch_id, e.mother_rabbit_id ), litter_stats as ( select l.batch_id, l.mother_rabbit_id, count(*) as litter_count, coalesce(sum(l.total_kits), 0) as total_kits, coalesce(sum(l.live_kits), 0) as live_kits, coalesce(sum(l.weaned_count), 0) as weaned_kits, coalesce(sum(l.current_nursing), 0) as current_nursing_kits, sum(case when l.status = 'NURSING' then 1 else 0 end) as nursing_litter_count from litters l where l.batch_id = #{batchId} group by l.batch_id, l.mother_rabbit_id ) select br.id, br.batch_id, br.rabbit_id, coalesce(cc.male_rabbit_id, br.male_rabbit_id) as male_rabbit_id, cs.latest_cycle_id, coalesce(ls.current_nursing_kits, 0) as current_nursing_kits, coalesce(ls.nursing_litter_count, 0) as nursing_litter_count, br.join_reason, br.batch_role, br.current_status, es.last_operation_at as last_event_date, case when br.batch_role = 'breeding' then cc.next_due_at else br.next_event_date end as next_event_date, case when br.batch_role = 'breeding' then null else br.next_event_type end as next_event_type, br.is_active, br.join_date, br.exit_date, r.type as rabbit_type, r.gender as rabbit_gender, r.cage_id, cc.stage as current_stage, cc.id as current_cycle_id, coalesce(cs.cycle_count, 0) as batch_cycle_count, coalesce(es.operation_count, 0) as batch_operation_count, coalesce(ls.litter_count, 0) as batch_litter_count, coalesce(ls.total_kits, 0) as batch_total_kits, coalesce(ls.live_kits, 0) as batch_live_kits, coalesce(ls.weaned_kits, 0) as batch_weaned_kits, es.last_operation_at as batch_last_operation_at from batch_rabbits br inner join batches b on b.id = br.batch_id inner join rabbits r on r.id = br.rabbit_id and r.house_id = b.house_id left join current_cycles cc on cc.batch_id = br.batch_id and cc.mother_rabbit_id = br.rabbit_id left join cycle_stats cs on cs.batch_id = br.batch_id and cs.mother_rabbit_id = br.rabbit_id left join event_stats es on es.batch_id = br.batch_id and es.mother_rabbit_id = br.rabbit_id left join litter_stats ls on ls.batch_id = br.batch_id and ls.mother_rabbit_id = br.rabbit_id where br.batch_id = #{batchId}
and br.batch_role = #{role}
and br.is_active = #{active}
order by br.id asc

with pending_by_cycle as ( select wt.cycle_id, min(wt.due_time) as next_due_at from work_tasks wt where wt.house_id = #{houseId} and wt.rabbit_id = #{rabbitId} and wt.status = 'PENDING' and wt.cycle_id is not null group by wt.cycle_id ), ranked_open_cycles as ( select c.id, c.batch_id, c.mother_rabbit_id, c.male_rabbit_id, c.stage, p.next_due_at, row_number() over ( partition by c.batch_id, c.mother_rabbit_id order by case when p.next_due_at is null then 1 else 0 end, p.next_due_at, case when c.stage = 'AWAIT_WEANING' then 1 else 0 end, c.cycle_no desc, c.id desc ) as row_no from breeding_cycles c left join pending_by_cycle p on p.cycle_id = c.id where c.house_id = #{houseId} and c.mother_rabbit_id = #{rabbitId} and c.lifecycle = 'OPEN' ), current_cycles as ( select * from ranked_open_cycles where row_no = 1 ), cycle_stats as ( select c.batch_id, c.mother_rabbit_id, count(*) as cycle_count, max(c.id) as latest_cycle_id from breeding_cycles c where c.house_id = #{houseId} and c.mother_rabbit_id = #{rabbitId} group by c.batch_id, c.mother_rabbit_id ), event_stats as ( select e.batch_id, e.mother_rabbit_id, count(*) as operation_count, max(e.occurred_at) as last_operation_at from repro_events e where e.house_id = #{houseId} and e.mother_rabbit_id = #{rabbitId} and e.batch_id is not null group by e.batch_id, e.mother_rabbit_id ), litter_stats as ( select l.batch_id, l.mother_rabbit_id, count(*) as litter_count, coalesce(sum(l.total_kits), 0) as total_kits, coalesce(sum(l.live_kits), 0) as live_kits, coalesce(sum(l.weaned_count), 0) as weaned_kits, coalesce(sum(l.current_nursing), 0) as current_nursing_kits, sum(case when l.status = 'NURSING' then 1 else 0 end) as nursing_litter_count from litters l where l.house_id = #{houseId} and l.mother_rabbit_id = #{rabbitId} and l.batch_id is not null group by l.batch_id, l.mother_rabbit_id ) select br.id, br.batch_id, br.rabbit_id, coalesce(cc.male_rabbit_id, br.male_rabbit_id) as male_rabbit_id, cs.latest_cycle_id, coalesce(ls.current_nursing_kits, 0) as current_nursing_kits, coalesce(ls.nursing_litter_count, 0) as nursing_litter_count, br.join_reason, br.batch_role, br.current_status, es.last_operation_at as last_event_date, case when br.batch_role = 'breeding' then cc.next_due_at else br.next_event_date end as next_event_date, case when br.batch_role = 'breeding' then null else br.next_event_type end as next_event_type, br.is_active, br.join_date, br.exit_date, r.type as rabbit_type, r.gender as rabbit_gender, r.cage_id, cc.stage as current_stage, cc.id as current_cycle_id, coalesce(cs.cycle_count, 0) as batch_cycle_count, coalesce(es.operation_count, 0) as batch_operation_count, coalesce(ls.litter_count, 0) as batch_litter_count, coalesce(ls.total_kits, 0) as batch_total_kits, coalesce(ls.live_kits, 0) as batch_live_kits, coalesce(ls.weaned_kits, 0) as batch_weaned_kits, es.last_operation_at as batch_last_operation_at from batch_rabbits br inner join batches b on b.id = br.batch_id inner join rabbits r on r.id = br.rabbit_id and r.house_id = b.house_id left join current_cycles cc on cc.batch_id = br.batch_id and cc.mother_rabbit_id = br.rabbit_id left join cycle_stats cs on cs.batch_id = br.batch_id and cs.mother_rabbit_id = br.rabbit_id left join event_stats es on es.batch_id = br.batch_id and es.mother_rabbit_id = br.rabbit_id left join litter_stats ls on ls.batch_id = br.batch_id and ls.mother_rabbit_id = br.rabbit_id where b.house_id = #{houseId} and r.house_id = #{houseId} and br.rabbit_id = #{rabbitId}
and br.is_active = #{active}
order by br.id asc
